    -- BP: cfg001 (post_reset — m_tready(0) stalled 10 cycles post-reset)
    p_bp_001 : process
    begin
        c001_mready(0) <= '0';
        c001_mready(C001_NUM_TAPS-1 downto 1) <= (others => '1');
        wait until c001_rst = '0';
        wait for CLK_PERIOD * 10;
        c001_mready <= (others => '1');
        wait;
    end process p_bp_001;

    -- BP: cfg055 (post_reset_last — m_tready(NUM_TAPS-1) stalled 10 cycles post-reset)
    p_bp_055 : process
    begin
        c055_mready(C055_NUM_TAPS-1) <= '0';
        c055_mready(C055_NUM_TAPS-2 downto 0) <= (others => '1');
        wait until c055_rst = '0';
        wait for CLK_PERIOD * 10;
        c055_mready <= (others => '1');
        wait;
    end process p_bp_055;

    -- BP: cfg040 (mid_sim — m_tready(0) stalled 15 cycles mid-sim)
    p_bp_040 : process
    begin
        wait until c040_rst = '0';
        wait for CLK_PERIOD * 210;
        c040_mready(0) <= '0';
        wait for CLK_PERIOD * 15;
        c040_mready(0) <= '1';
        wait;
    end process p_bp_040;

    -- Stimulus processes

    p_stim001 : process
        file     f   : text;
        variable ln  : line;
        variable pv  : integer;
        variable col : natural range 0 to 8-1;
        variable row : natural range 0 to 8-1;
    begin
        wait for CLK_PERIOD * 5;
        wait until rising_edge(clk);
        c001_rst <= '0';
        file_open(f, C001_IN_FILE, read_mode);
        col := 0;  row := 0;
        while not endfile(f) loop
            readline(f, ln);  read(ln, pv);
            c001_sdata  <= std_logic_vector(to_unsigned(pv, C001_DW));
            c001_svalid <= '1';
            if row = 0 and col = 0 then c001_suser <= '1'; else c001_suser <= '0'; end if;
            if col = 8-1 then c001_slast <= '1'; else c001_slast <= '0'; end if;
            wait until rising_edge(clk) and c001_sready = '1';
            if col = 8-1 then
                col := 0;
                if row = 8-1 then row := 0; else row := row+1; end if;
            else
                col := col+1;
            end if;
        end loop;
        c001_svalid <= '0';  c001_slast <= '0';  c001_suser <= '0';
        file_close(f);
        wait;
    end process p_stim001;

