        variable pv  : integer;
        variable col : natural range 0 to 5-1;
        variable row : natural range 0 to 5-1;
    begin
        wait for CLK_PERIOD * 5;
        wait until rising_edge(clk);
        c323_rst <= '0';
        file_open(f, C323_IN_FILE, read_mode);
        col := 0;  row := 0;
        while not endfile(f) loop
            readline(f, ln);  read(ln, pv);
            c323_sdata  <= std_logic_vector(to_unsigned(pv, C323_DW));
            c323_svalid <= '1';
            if row = 0 and col = 0 then c323_suser <= '1'; else c323_suser <= '0'; end if;
            if col = 5-1 then c323_slast <= '1'; else c323_slast <= '0'; end if;
            wait until rising_edge(clk) and c323_sready = '1';
            if col = 5-1 then
                col := 0;
                if row = 5-1 then row := 0; else row := row+1; end if;
            else
                col := col+1;
            end if;
        end loop;
        c323_svalid <= '0';  c323_slast <= '0';  c323_suser <= '0';
        file_close(f);
        wait;
    end process p_stim323;

    p_stim324 : process
        file     f   : text;
        variable ln  : line;
        variable pv  : integer;
        variable col : natural range 0 to 8-1;
        variable row : natural range 0 to 1-1;
    begin
        wait for CLK_PERIOD * 5;
        wait until rising_edge(clk);
        c324_rst <= '0';
        file_open(f, C324_IN_FILE, read_mode);
        col := 0;  row := 0;
