            if col = 8-1 then c324_slast <= '1'; else c324_slast <= '0'; end if;
            wait until rising_edge(clk) and c324_sready = '1';
            if col = 8-1 then
                col := 0;
                if row = 1-1 then row := 0; else row := row+1; end if;
            else
                col := col+1;
            end if;
        end loop;
        c324_svalid <= '0';  c324_slast <= '0';  c324_suser <= '0';
        file_close(f);
        wait;
    end process p_stim324;

