            wait until rising_edge(clk) and c001_mvalid = '1' and (and c001_mready) = '1';
            readline(f, ln);
            for tap in 0 to 9-1 loop
                read(ln, tv);
                exp_vec((tap+1)*8-1 downto tap*8)
                    := std_logic_vector(to_unsigned(tv, 8));
